{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Brigatinib, a piperazine-containing aminoheteroaryl kinase inhibitor closely related to the query, has an absolute oral bioavailability of 46% in healthy volunteers, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "A high-transfer record for the same piperazine-aminoheteroaryl scaffold reports 77% absolute oral bioavailability in fed healthy volunteers, showing this chemotype can be well absorbed despite high TPSA and ionization.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "In the fasted state, the same scaffold achieved 57% absolute oral bioavailability, reinforcing that the piperazine-aminoheteroaryl class is orally bioavailable above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Trametinib, a pyridopyrimidinone kinase inhibitor with multiple aromatic and heteroaromatic features, has 72% oral bioavailability in fasted patients, supporting high F for the query's similar kinase-inhibitor scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Brepocitinib, an aminoheteroaryl kinase inhibitor, has 75% absolute oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Norfloxacin, a piperazine-containing heteroaromatic drug, has a mean oral bioavailability of 40% (range 22–60%), supporting F ≥20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is palbociclib, a piperazine-containing pyridopyrimidinone kinase inhibitor. High-transfer experimental analogues with the same piperazine-aminoheteroaryl kinase-inhibitor phenotype show absolute oral bioavailability of 46–77%, and related kinase inhibitors show 40–75%. These direct measurements outweigh the physicochemical prior of low neutral fraction and high TPSA. Therefore predict high (F ≥20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself was included in the evidence set; prediction relies on high-transfer analogues.",
    "Some high-transfer records have inconsistent compound names versus SMILES (e.g., GSK1322322 vs brigatinib), introducing minor source uncertainty.",
    "Low-transfer records (vinpocetine, TFMPP, mCPP) were excluded because transfer likelihood is 0; they do not provide threshold-relevant evidence."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C10"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "piperazine-aminoheteroaryl kinase inhibitors"
    }
  ],
  "revision_action": "initial"
}

